package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import io.swagger.v3.oas.annotations.security.SecurityRequirements;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/reviews") public class ReviewController {private final ReviewService service;public ReviewController(ReviewService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@PostMapping public ResponseEntity<ApiResponse<ReviewResponse>> create(@Valid @RequestBody ReviewRequest r,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Review created",service.create(r)));}@SecurityRequirements @GetMapping("/{id}") public ApiResponse<ReviewResponse> get(@PathVariable UUID id,HttpServletRequest h){return ok(h,"Review retrieved",service.get(id));}@SecurityRequirements @GetMapping public ApiResponse<PageResponse<ReviewResponse>> search(@RequestParam(required=false) Long productId,@RequestParam(required=false) Short rating,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,HttpServletRequest h){return ok(h,"Reviews retrieved",service.search(productId,rating,page,size));}@PatchMapping("/{id}") public ApiResponse<ReviewResponse> update(@PathVariable UUID id,@Valid @RequestBody UpdateReviewRequest r,HttpServletRequest h){return ok(h,"Review updated",service.update(id,r));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}@SecurityRequirements @GetMapping("/products/{productId}/rating-summary") public ApiResponse<RatingSummaryResponse> rating(@PathVariable Long productId,HttpServletRequest h){return ok(h,"Rating summary retrieved",service.rating(productId));}
@GetMapping("/eligibility") public ApiResponse<com.lbos.commercecustomer.dto.client.order.ReviewEligibilityResponse> eligibility(@RequestParam Long productId,HttpServletRequest h){return ok(h,"Review eligibility resolved",service.eligibility(productId));}}